(()=>{
const c=window.AVID_CONTENT||{};
const safeURL=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:null}catch{return null}};
const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
const brand=document.querySelector('#fitting-brands');if(brand)(c.brands||[]).forEach(name=>brand.append(make('div',name,'brand-tile')));
function entries(selector,items){const host=document.querySelector(selector);if(!host||!items?.length)return;host.replaceChildren();items.forEach(item=>{const article=make('article');article.append(make('span',item.date,'eyebrow'),make('h3',item.title),make('p',item.description));const url=safeURL(item.url);if(url){const a=make('a','View details ↗','text-link');a.href=url;a.target='_blank';a.rel='noopener';article.append(a)}host.append(article)})}
entries('#clinics',c.clinics);entries('#demo-days',c.demoDays);
const quotes=document.querySelector('#testimonials');if(quotes&&c.testimonials?.length){quotes.replaceChildren();c.testimonials.forEach(item=>{const q=make('blockquote',item.quote,'quote');q.append(make('cite',item.name));quotes.append(q)})}
const winners=document.querySelector('#weekly-winners');if(winners&&c.weeklyWinners?.length){winners.replaceChildren();winners.classList.add('winner-grid');c.weeklyWinners.forEach(item=>{const e=make('article',null,'winner-card');e.append(make('span',item.week,'eyebrow'),make('h3',item.contest),make('p',item.winner),make('p',item.result));winners.append(e)})}
const board=document.querySelector('#leaderboard');const boardURL=safeURL(c.leaderboardEmbedUrl);if(board&&boardURL&&new URL(boardURL).hostname==='docs.google.com'&&new URL(boardURL).pathname.startsWith('/spreadsheets/')){board.replaceChildren();const frame=make('iframe',null,'leaderboard-frame');frame.title='AVID Golf league leaderboard';frame.src=boardURL;frame.loading='lazy';frame.referrerPolicy='no-referrer';board.append(frame);const note=make('p','Standings are supplied by our Google Sheet. Changes may take a few minutes to appear.','note');board.append(note);const publicURL=safeURL(c.leaderboardPublicUrl);if(publicURL){const a=make('a','Open leaderboard in a new tab ↗','text-link');a.href=publicURL;a.target='_blank';a.rel='noopener';board.append(a)}}
const gift=document.querySelector('#egift-link');if(gift&&safeURL(c.toastGiftCardUrl)){gift.href=safeURL(c.toastGiftCardUrl);const giftNote=document.querySelector('#egift-note');if(giftNote)giftNote.textContent='Choose an amount and complete your e-gift card purchase securely with Toast.'}
if(safeURL(c.fittingUrl))document.querySelectorAll('a[href="https://avidfittings.as.me/schedule/3d726a1b"]').forEach(a=>a.href=safeURL(c.fittingUrl));
document.querySelectorAll('[data-season]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-season]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-season-panel]').forEach(panel=>panel.hidden=panel.dataset.seasonPanel!==button.dataset.season)}));
document.addEventListener('click',e=>{document.querySelectorAll('.all-pages[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.all-pages[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus()})});
const form=document.querySelector('#event-form');if(form){const date=form.elements.date;const today=new Date();date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');const review=document.querySelector('#inquiry-review');const body=document.querySelector('#inquiry-text');let message='';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));message='Event inquiry for AVID Golf\n\n'+[['Name',data.name],['Email',data.email],['Phone',data.phone||'Not provided'],['Event type',data.eventType],['Preferred date',data.date],['Preferred time (Winnipeg)',data.time],['Number of guests',data.guests],['Duration',data.duration],['Rental clubs',data.rentals],['Menu / food preorder',data.food],['Other requests',data.details||'None provided']].map(([k,v])=>k+': '+v).join('\n');body.textContent=message;document.querySelector('#send-inquiry').href='mailto:'+(c.eventEmail||'info@AVIDGOLF.club')+'?subject='+encodeURIComponent('Event inquiry — '+data.eventType+' — '+data.date)+'&body='+encodeURIComponent(message);form.hidden=true;review.hidden=false;review.focus();review.scrollIntoView({block:'center'})});document.querySelector('#edit-inquiry').addEventListener('click',()=>{review.hidden=true;form.hidden=false;form.elements.name.focus()});document.querySelector('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);document.querySelector('#copy-status').textContent='Copied. Paste into an email to '+(c.eventEmail||'info@AVIDGOLF.club')+'.'}catch{document.querySelector('#copy-status').textContent='Select and copy the inquiry text above, then email it to '+(c.eventEmail||'info@AVIDGOLF.club')+'.'}})}
})();
